const ROLE_ANALYTICS_COPY = {
  Administrator: {title:'Platform telemetry', subtitle:'Operational volume, service evidence and risk posture from stored scan records.', labels:['Ingest volume','Risk exposure','Severity posture']},
  'SOC Team Member': {title:'SOC triage analytics', subtitle:'Prioritize the alert queue by severity, timing and risk distribution.', labels:['Alert volume','Triage priority','Severity posture']},
  'Security Analyst': {title:'Investigation analytics', subtitle:'Compare static evidence, YARA matches, model availability and risk for investigated files.', labels:['Evidence volume','YARA coverage','Severity posture']},
  Researcher: {title:'Research analytics', subtitle:'Explore observed file types, measured features and result distributions; no ground-truth accuracy is inferred.', labels:['Sample volume','Observed indicators','Severity posture']}
};
const DEMO_SCANS = Array.from({length:8},(_,i)=>{const d=new Date();d.setDate(d.getDate()-(7-i));d.setHours(9+(i*3)%12,15,0,0);const severity=['low','medium','high','critical','medium','high','low','critical'][i];const risk=[12,38,76,91,44,68,19,84][i];return {id:`demo-${i}`,filename:['invoice_review.exe','sample_clean.bin','script_bundle.dll','unknown_loader.exe','document_scan.pdf','packed_sample.bin','telemetry_test.dat','demo_alert.exe'][i],file_type:['application/x-dosexec','application/octet-stream','application/x-dosexec','application/x-dosexec','application/pdf','application/octet-stream','application/octet-stream','application/x-dosexec'][i],verdict:risk>=60?'malicious_suspected':risk>=30?'suspicious':'no_strong_indicators',severity,risk_score:risk,yara_count:[0,0,2,3,1,2,0,4][i],ml_score:[0.08,0.21,0.82,0.94,0.46,0.71,0.13,0.89][i],ml_prediction:{available:i!==1,label:risk>=60?'Malware':'Benign'},features:{is_pe:[1,0,1,1,0,0,0,1][i],entropy:[4.1,5.8,7.2,7.7,3.4,6.9,4.7,7.4][i],url_count:[0,0,2,3,1,1,0,4][i],ip_count:[0,0,1,2,0,1,0,2][i]},file_size:[58320,1240,90210,152400,8000,77800,3400,132500][i],created_at:d.toISOString()};});
function RoleAnalytics({items=[],role}) {
 const hasRealScans=(items||[]).length>0; const scans=hasRealScans?items:DEMO_SCANS; const copy=ROLE_ANALYTICS_COPY[role]||ROLE_ANALYTICS_COPY['Security Analyst'];
 const count=(fn)=>scans.filter(fn).length;
 const severityKeys=['low','medium','high','critical'];
 const sev=Object.fromEntries(severityKeys.map(k=>[k,count(x=>String(x.severity||'').toLowerCase()===k)]));
 const verdictCounts={}; scans.forEach(x=>{const k=x.verdict||'unknown';verdictCounts[k]=(verdictCounts[k]||0)+1;});
 const dayCounts={}; scans.forEach(x=>{const d=x.created_at?new Date(x.created_at).toISOString().slice(0,10):'unknown';dayCounts[d]=(dayCounts[d]||0)+1;});
 const dates=Object.keys(dayCounts).sort().slice(-14);
 const weekdays=['Sun','Mon','Tue','Wed','Thu','Fri','Sat']; const heat={};
 scans.forEach(x=>{if(!x.created_at)return;const d=new Date(x.created_at);const key=`${d.getDay()}-${d.getHours()}`;heat[key]=(heat[key]||0)+1;});
 const heatData=[];for(let day=0;day<7;day++)for(let hour=0;hour<24;hour++)heatData.push([hour,day,heat[`${day}-${hour}`]||0]);
 const stackData=dates.map(d=>({date:d,...Object.fromEntries(severityKeys.map(k=>[k,scans.filter(x=>x.created_at&&new Date(x.created_at).toISOString().slice(0,10)===d&&String(x.severity||'').toLowerCase()===k).length]))}));
 const avg=(fn)=>scans.length?Number((scans.reduce((a,x)=>a+(Number(fn(x))||0),0)/scans.length).toFixed(2)):0;
 const typeCounts={};scans.forEach(x=>{const k=x.file_type||'unknown';typeCounts[k]=(typeCounts[k]||0)+1;});
 const roleIsSoc=role==='SOC Team Member', roleIsAnalyst=role==='Security Analyst', roleIsResearcher=role==='Researcher';
 const roleDaily=dates.map(d=>{const xs=scans.filter(x=>x.created_at&&new Date(x.created_at).toISOString().slice(0,10)===d);if(roleIsSoc)return xs.filter(x=>['high','critical'].includes(String(x.severity||'').toLowerCase())).length;if(roleIsAnalyst)return xs.reduce((a,x)=>a+(x.yara_count||0),0);if(roleIsResearcher){const vals=xs.map(x=>Number(x.features?.entropy)).filter(Number.isFinite);return vals.length?Number((vals.reduce((a,b)=>a+b,0)/vals.length).toFixed(2)):0;}return xs.length;});
 const barObj=roleIsSoc?sev:roleIsAnalyst?{'YARA matched':count(x=>(x.yara_count||0)>0),'ML available':count(x=>x.ml_prediction?.available),'PE files':count(x=>x.features?.is_pe),'URL indicators':count(x=>(x.features?.url_count||0)>0)}:roleIsResearcher?typeCounts:verdictCounts;
 const donutObj=roleIsAnalyst?{'ML available':count(x=>x.ml_prediction?.available),'ML unavailable':count(x=>!x.ml_prediction?.available),'YARA matched':count(x=>(x.yara_count||0)>0),'No YARA match':count(x=>(x.yara_count||0)===0)}:roleIsResearcher?typeCounts:sev;
 const scatterData=scans.filter(x=>!roleIsAnalyst||x.ml_score!==null&&x.ml_score!==undefined).map(x=>roleIsAnalyst?[Number(x.ml_score)*100,Number(x.risk_score),x.filename||'file']:roleIsSoc?[Number(x.yara_count||0),Number(x.risk_score||0),x.filename||'file']:roleIsResearcher?[Number(x.file_size||0),Number(x.features?.entropy),x.filename||'file']:[Number(x.file_size||0),Number(x.risk_score||0),x.filename||'file']).filter(x=>x.every((v,i)=>i===2||Number.isFinite(v)));
 const histogramInput=scans.filter(x=>!roleIsAnalyst||x.ml_score!==null&&x.ml_score!==undefined).map(x=>roleIsResearcher?Number(x.features?.entropy):roleIsAnalyst?(Number(x.ml_score)*100):Number(x.risk_score)).filter(Number.isFinite);const histMax=roleIsResearcher?8:100;const hist=Array.from({length:5},(_,i)=>{const lo=histMax*i/5,hi=histMax*(i+1)/5;return {label:`${lo.toFixed(0)}–${hi.toFixed(0)}`,value:histogramInput.filter(v=>v>=lo&&(i===4?v<=hi:v<hi)).length}});
 const radar=roleIsAnalyst?[{name:'YARA coverage',value:Math.min(100,avg(x=>(x.yara_count||0)*20))},{name:'ML availability',value:avg(x=>x.ml_prediction?.available?100:0)},{name:'PE coverage',value:avg(x=>x.features?.is_pe?100:0)},{name:'URL indicators',value:Math.min(100,avg(x=>(x.features?.url_count||0)*10))},{name:'Mean risk',value:avg(x=>x.risk_score)}]:roleIsSoc?[{name:'High severity',value:avg(x=>['high','critical'].includes(String(x.severity||'').toLowerCase())?100:0)},{name:'Critical',value:avg(x=>String(x.severity||'').toLowerCase()==='critical'?100:0)},{name:'YARA alerts',value:Math.min(100,avg(x=>(x.yara_count||0)*20))},{name:'Mean risk',value:avg(x=>x.risk_score)},{name:'Alert volume',value:Math.min(100,scans.length)}]:roleIsResearcher?[{name:'Entropy',value:Math.min(100,avg(x=>(x.features?.entropy||0)*12.5))},{name:'PE files',value:avg(x=>x.features?.is_pe?100:0)},{name:'URLs',value:Math.min(100,avg(x=>(x.features?.url_count||0)*10))},{name:'IP indicators',value:Math.min(100,avg(x=>(x.features?.ip_count||0)*10))},{name:'ML available',value:avg(x=>x.ml_prediction?.available?100:0)}]:[{name:'Risk score',value:avg(x=>x.risk_score)},{name:'High risk',value:avg(x=>['high','critical'].includes(String(x.severity||'').toLowerCase())?100:0)},{name:'ML available',value:avg(x=>x.ml_prediction?.available?100:0)},{name:'YARA matches',value:Math.min(100,avg(x=>(x.yara_count||0)*20))},{name:'PE evidence',value:avg(x=>x.features?.is_pe?100:0)}];
 const treemapObj=roleIsAnalyst?{'YARA evidence':count(x=>(x.yara_count||0)>0),'ML evidence':count(x=>x.ml_prediction?.available),'PE evidence':count(x=>x.features?.is_pe),'URL indicators':count(x=>(x.features?.url_count||0)>0)}:roleIsSoc?sev:typeCounts;
 const stackSeries=roleIsAnalyst?[{name:'YARA matched',data:dates.map(d=>scans.filter(x=>x.created_at&&new Date(x.created_at).toISOString().slice(0,10)===d&&(x.yara_count||0)>0).length)},{name:'ML available',data:dates.map(d=>scans.filter(x=>x.created_at&&new Date(x.created_at).toISOString().slice(0,10)===d&&x.ml_prediction?.available).length)},{name:'PE files',data:dates.map(d=>scans.filter(x=>x.created_at&&new Date(x.created_at).toISOString().slice(0,10)===d&&x.features?.is_pe).length)}]:roleIsResearcher?Object.keys(verdictCounts).map((name,i)=>({name,data:dates.map(d=>scans.filter(x=>x.created_at&&new Date(x.created_at).toISOString().slice(0,10)===d&&(x.verdict||'unknown')===name).length)})):severityKeys.map((k,i)=>({name:k,data:stackData.map(x=>x[k])}));
 const chartText={color:'#c7c7c7'}; const grid={left:42,right:16,top:24,bottom:38};
 const panels=[
  {title:roleIsSoc?'High-risk alert trend':roleIsAnalyst?'YARA evidence trend':roleIsResearcher?'Mean entropy by day':'Platform scan volume trend',kind:'Line chart',option:{tooltip:{trigger:'axis'},grid,xAxis:{type:'category',data:dates,axisLabel:chartText},yAxis:{type:'value',axisLabel:chartText,splitLine:{lineStyle:{color:'#303030'}}},series:[{name:roleIsSoc?'High-risk alerts':roleIsAnalyst?'YARA matches':roleIsResearcher?'Mean entropy':'Scans',type:'line',smooth:true,data:roleDaily,areaStyle:{opacity:.12},lineStyle:{color:'#ef233c',width:3}}]}},
  {title:roleIsSoc?'Severity priority counts':roleIsAnalyst?'Observed evidence channels':roleIsResearcher?'File type distribution':'Verdict distribution',kind:'Bar chart',option:{tooltip:{trigger:'axis'},grid,xAxis:{type:'value',axisLabel:chartText,splitLine:{lineStyle:{color:'#303030'}}},yAxis:{type:'category',data:Object.keys(barObj),axisLabel:chartText},series:[{type:'bar',data:Object.values(barObj),itemStyle:{color:'#ef233c',borderRadius:[0,4,4,0]}}]}},
  {title:`${copy.labels[2]} · composition`,kind:'Donut chart',option:{tooltip:{trigger:'item'},legend:{bottom:0,textStyle:chartText},series:[{type:'pie',radius:['42%','72%'],data:Object.entries(donutObj).map(([name,value])=>({name,value})),label:{color:'#ddd'}}]}},
  {title:'Scan time heatmap',kind:'Heatmap',option:{tooltip:{position:'top'},grid:{left:42,right:14,top:18,bottom:40},xAxis:{type:'category',data:Array.from({length:24},(_,i)=>String(i).padStart(2,'0')),axisLabel:chartText},yAxis:{type:'category',data:weekdays,axisLabel:chartText},visualMap:{min:0,max:Math.max(1,...heatData.map(x=>x[2])),calculable:true,orient:'horizontal',left:'center',bottom:0,textStyle:chartText},series:[{type:'heatmap',data:heatData}] }},
  {title:roleIsAnalyst?'ML score vs heuristic risk':roleIsSoc?'YARA matches vs risk':roleIsResearcher?'File size vs entropy':'File size vs risk score',kind:'Scatter plot',option:{tooltip:{formatter:p=>`${p.data[2]}<br/>X: ${p.data[0]}<br/>Y: ${p.data[1]}`},grid,xAxis:{type:'value',name:roleIsAnalyst?'ML score %':roleIsSoc?'YARA matches':'File size bytes',axisLabel:chartText,splitLine:{lineStyle:{color:'#303030'}}},yAxis:{type:'value',name:roleIsResearcher?'Entropy':'Risk / 100',min:0,max:roleIsResearcher?8:100,axisLabel:chartText,splitLine:{lineStyle:{color:'#303030'}}},series:[{type:'scatter',symbolSize:8,data:scatterData,itemStyle:{color:'#ef233c',opacity:.8}}]}},
  {title:roleIsAnalyst?'Investigation evidence by day':roleIsResearcher?'Research verdicts by day':roleIsSoc?'Severity mix by day':'Platform severity mix by day',kind:'Stacked bar',option:{tooltip:{trigger:'axis'},legend:{textStyle:chartText},grid,xAxis:{type:'category',data:dates,axisLabel:chartText},yAxis:{type:'value',axisLabel:chartText,splitLine:{lineStyle:{color:'#303030'}}},series:stackSeries.map((x,i)=>({name:x.name,type:'bar',stack:'total',data:x.data,itemStyle:{color:['#a7a7a7','#efb34c','#ef233c','#8f1022'][i%4]}}))}},
  {title:'Triage funnel',kind:'Funnel',option:{tooltip:{trigger:'item'},series:[{type:'funnel',left:'10%',top:15,bottom:15,width:'80%',min:0,max:Math.max(1,scans.length),sort:'descending',gap:4,label:{color:'#eee',formatter:'{b}: {c}'},data:[{name:'All scans',value:scans.length},{name:'Medium+',value:count(x=>['medium','high','critical'].includes(String(x.severity||'').toLowerCase()))},{name:'High+',value:count(x=>['high','critical'].includes(String(x.severity||'').toLowerCase()))},{name:'Critical',value:sev.critical}]}]}},
  {title:roleIsResearcher?'Entropy distribution':roleIsAnalyst?'ML score distribution':'Risk score histogram',kind:'Histogram',option:{tooltip:{trigger:'axis'},grid,xAxis:{type:'category',data:hist.map(x=>x.label),axisLabel:chartText,name:roleIsResearcher?'Entropy':roleIsAnalyst?'ML score %':'Risk score'},yAxis:{type:'value',axisLabel:chartText,splitLine:{lineStyle:{color:'#303030'}}},series:[{type:'bar',data:hist.map(x=>x.value),barMaxWidth:38,itemStyle:{color:'#ef233c'}}]}},
  {title:role==='Security Analyst'?'Evidence profile':role==='Researcher'?'Measured feature profile':role==='SOC Team Member'?'Triage profile':'Platform risk profile',kind:'Radar chart',option:{tooltip:{},radar:{indicator:radar.map(x=>({name:x.name,max:100})),axisName:{color:'#ccc'},splitLine:{lineStyle:{color:'#343434'}},splitArea:{areaStyle:{color:['rgba(255,255,255,.01)','rgba(255,255,255,.025)']}}},series:[{type:'radar',data:[{value:radar.map(x=>x.value),name:'Observed average',areaStyle:{color:'rgba(239,35,60,.18)'},lineStyle:{color:'#ef233c'}}]}]}},
  {title:roleIsAnalyst?'Evidence channel treemap':roleIsSoc?'Severity treemap':'Observed file-type mix',kind:'Treemap',option:{tooltip:{formatter:p=>`${p.name}: ${p.value} scans`},series:[{type:'treemap',roam:false,nodeClick:false,breadcrumb:{show:false},label:{color:'#fff',formatter:'{b}\n{c}'},data:Object.entries(treemapObj).map(([name,value])=>({name,value,itemStyle:{color:['#ef233c','#a51428','#5e5e5e','#888'][Math.abs(name.length)%4]}}))}]}}
 ];
 return <section className="role-analytics"><div className="panelhead"><div><h3>{copy.title}</h3><small>{copy.subtitle} {hasRealScans?'Charts use persisted scan records.':'No saved scans yet — showing clearly labelled demo data so the charts are visible immediately.'}</small></div><Badge kind={hasRealScans?'green':'red'}>{hasRealScans?'REAL SCAN DATA':'DEMO DATA'}</Badge></div><div className="role-chart-grid">{panels.map(p=><article className="panel role-chart" key={p.title}><div className="panelhead"><div><h4>{p.title}</h4><small>{p.kind}</small></div></div><ECharts option={p.option} style={{height:230}} notMerge lazyUpdate/><p className="chart-explain">{p.title.toLowerCase().includes('heatmap')?'Counts by weekday and hour using stored scan timestamps.':p.title.includes('Scatter')?'Each point is one stored scan; correlation is descriptive, not causal.':p.title.includes('funnel')?'Stages are nested severity counts from scan records, not a measured workflow conversion rate.':p.title.includes('histogram')?'Risk scores are grouped into fixed ranges to show the stored score distribution.':p.title.includes('Radar')?'Values are normalized descriptive averages; not a classifier accuracy or ground-truth metric.':p.title.includes('Treemap')?'Groups scans by the file type recorded by the analyzer.':hasRealScans?'Computed from persisted scan records.':'Illustrative synthetic observations for interface preview only; not scan results.'}</p></article>)}</div></section>;
}

function RoleWorkflowPage({page,role,scans,openScan,refresh}) {
 const [users,setUsers]=useState([]),[audit,setAudit]=useState([]),[health,setHealth]=useState(null),[modelState,setModelState]=useState(null),[rules,setRules]=useState(null),[note,setNote]=useState(''),[notes,setNotes]=useState([]),[busy,setBusy]=useState(false),[error,setError]=useState(''),[ruleFile,setRuleFile]=useState(null),[rulesetFile,setRulesetFile]=useState(null),[rulesetSource,setRulesetSource]=useState(''),[rulesetVersion,setRulesetVersion]=useState(''),[rulesetLicense,setRulesetLicense]=useState(''),[rulesets,setRulesets]=useState([]),[newUserName,setNewUserName]=useState(''),[newUserEmail,setNewUserEmail]=useState(''),[newUserPassword,setNewUserPassword]=useState(''),[newUserRole,setNewUserRole]=useState('researcher'),[incidents,setIncidents]=useState([]),[assignees,setAssignees]=useState([]),[incidentScanId,setIncidentScanId]=useState(''),[incidentTitle,setIncidentTitle]=useState(''),[incidentNotes,setIncidentNotes]=useState(''),[annotations,setAnnotations]=useState([]),[annotationScanId,setAnnotationScanId]=useState(''),[annotationLabel,setAnnotationLabel]=useState('unknown'),[annotationFamily,setAnnotationFamily]=useState(''),[annotationSource,setAnnotationSource]=useState('local scan'),[annotationNotes,setAnnotationNotes]=useState(''),[noteTitle,setNoteTitle]=useState('Experiment note'),[noteTags,setNoteTags]=useState('');
 useEffect(()=>{let live=true;setError('');const jobs=[];if(page==='Administration'||page==='Audit Review')jobs.push(api('/api/admin/users').then(v=>{if(live)setUsers(v)}).catch(e=>{if(live)setError(e.message)}));if(page==='Audit Review')jobs.push(api('/api/admin/audit').then(v=>{if(live)setAudit(v)}).catch(e=>{if(live)setError(e.message)}));if(page==='System Health')jobs.push(api('/health').then(v=>{if(live)setHealth(v)}).catch(e=>{if(live)setError(e.message)}));if(['Model Readiness','System Health'].includes(page))jobs.push(api('/api/model/readiness').then(v=>{if(live)setModelState(v)}).catch(e=>{if(live)setError(e.message)}));if(['YARA Library','Rule Updates','Rule Match Explorer'].includes(page))jobs.push(api('/api/yara/rules').then(v=>{if(live)setRules(v)}).catch(e=>{if(live)setError(e.message)}));if(page==='Rule Updates')jobs.push(api('/api/yara/rulesets').then(v=>{if(live)setRulesets(v.rulesets||[])}).catch(e=>{if(live)setError(e.message)}));if(page==='Incident Queue'){jobs.push(api('/api/incidents').then(v=>{if(live)setIncidents(v)}).catch(e=>{if(live)setError(e.message)}));jobs.push(api('/api/incidents/assignees').then(v=>{if(live)setAssignees(v)}).catch(e=>{if(live)setError(e.message)}));}if(['Dataset Explorer','Family Research'].includes(page))jobs.push(api('/api/research/annotations').then(v=>{if(live)setAnnotations(v)}).catch(e=>{if(live)setError(e.message)}));if(page==='Experiment Notes')jobs.push(api('/api/research/notes').then(v=>{if(live)setNotes(v)}).catch(e=>{if(live)setError(e.message)}));return()=>{live=false;};},[page]);
 async function changeRole(id,role){setBusy(true);setError('');try{await api(`/api/admin/users/${id}/role`,{method:'PATCH',body:JSON.stringify({role})});setUsers(await api('/api/admin/users'));}catch(e){setError(e.message)}finally{setBusy(false)}}
 async function createManagedUser(e){e.preventDefault();setBusy(true);setError('');try{await api('/api/admin/users',{method:'POST',body:JSON.stringify({full_name:newUserName,email:newUserEmail,password:newUserPassword,role:newUserRole})});setUsers(await api('/api/admin/users'));setNewUserName('');setNewUserEmail('');setNewUserPassword('');}catch(e){setError(e.message)}finally{setBusy(false)}}
 async function changeStatus(id,active){setBusy(true);setError('');try{await api(`/api/admin/users/${id}/status`,{method:'PATCH',body:JSON.stringify({active})});setUsers(await api('/api/admin/users'));}catch(e){setError(e.message)}finally{setBusy(false)}}
 async function uploadRule(e){e.preventDefault();if(!ruleFile)return;setBusy(true);setError('');try{const fd=new FormData();fd.append('file',ruleFile);await api('/api/yara/rules',{method:'POST',body:fd});setRuleFile(null);setRules(await api('/api/yara/rules'));e.target.reset();}catch(e){setError(e.message)}finally{setBusy(false)}}
 async function removeRule(name){if(!window.confirm(`Remove local YARA rule file ${name}?`))return;setBusy(true);setError('');try{await api(`/api/yara/rules/${encodeURIComponent(name)}`,{method:'DELETE'});setRules(await api('/api/yara/rules'));}catch(e){setError(e.message)}finally{setBusy(false)}}
 async function importRuleset(e){e.preventDefault();if(!rulesetFile)return;setBusy(true);setError('');try{const fd=new FormData();fd.append('file',rulesetFile);fd.append('source',rulesetSource);fd.append('version',rulesetVersion);fd.append('license_name',rulesetLicense);await api('/api/yara/ruleset',{method:'POST',body:fd});setRulesetFile(null);setRules(await api('/api/yara/rules'));const r=await api('/api/yara/rulesets');setRulesets(r.rulesets||[]);e.target.reset();}catch(e){setError(e.message)}finally{setBusy(false)}}
 async function createIncident(e){e.preventDefault();setBusy(true);setError('');try{await api('/api/incidents',{method:'POST',body:JSON.stringify({scan_id:Number(incidentScanId),title:incidentTitle,notes:incidentNotes})});setIncidents(await api('/api/incidents'));setIncidentTitle('');setIncidentNotes('');}catch(e){setError(e.message)}finally{setBusy(false)}}
 async function updateIncident(id,payload){setBusy(true);setError('');try{await api(`/api/incidents/${id}`,{method:'PATCH',body:JSON.stringify(payload)});setIncidents(await api('/api/incidents'));}catch(e){setError(e.message)}finally{setBusy(false)}}
 async function saveAnnotation(e){e.preventDefault();setBusy(true);setError('');try{await api('/api/research/annotations',{method:'POST',body:JSON.stringify({scan_id:Number(annotationScanId),ground_truth:annotationLabel,family:annotationFamily||null,dataset_source:annotationSource,notes:annotationNotes})});setAnnotations(await api('/api/research/annotations'));setAnnotationNotes('');}catch(e){setError(e.message)}finally{setBusy(false)}}
 async function saveResearchNote(e){e.preventDefault();setBusy(true);setError('');try{await api('/api/research/notes',{method:'POST',body:JSON.stringify({title:noteTitle,content:note,tags:noteTags})});setNotes(await api('/api/research/notes'));setNote('');}catch(e){setError(e.message)}finally{setBusy(false)}}
 async function deleteResearchNote(id){setBusy(true);setError('');try{await api(`/api/research/notes/${id}`,{method:'DELETE'});setNotes(await api('/api/research/notes'));}catch(e){setError(e.message)}finally{setBusy(false)}}
 const high=[...scans].filter(x=>['high','critical'].includes(String(x.severity||'').toLowerCase())||Number(x.risk_score)>=60).sort((a,b)=>(b.risk_score||0)-(a.risk_score||0));
 const counts={low:0,medium:0,high:0,critical:0};scans.forEach(x=>{const k=String(x.severity||'').toLowerCase();if(k in counts)counts[k]++});
 const pageCopy={
 'Model Readiness':'Checks actual model and schema availability. A present artifact is not proof of feature compatibility or predictive quality.',
 'Rule Updates':'Inventory local YARA files and their compile status. Upstream rule feeds are not auto-downloaded; review licenses and test changes before deployment.',
 'Audit Review':'Administrator-only audit records for authentication and account-management events.',
 'System Health':'Live service reachability and scanner readiness signals.',
 'Alert Triage':'Sort real scan records by risk and severity, then open the evidence before escalation.',
 'Incident Queue':'A triage queue derived from stored high-risk scans. This build does not claim to be a full ITSM incident platform.',
 'Threat Timeline':'Time-ordered scan observations from the current database.',
 'Response Playbooks':'Checklist for repeatable evidence handling. Completion is local to this browser session and is not an incident record.',
 'Shift Handover':'Export the currently visible high-risk records and preserve hashes, timestamps and analyst notes.',
 'Rule Match Explorer':'Browse local rule inventory and open stored scan evidence to inspect actual match names, tags, metadata and matched strings.',
 'File Indicators':'Open scan details to inspect observed hashes, URLs, IPs, strings and PE information when extracted.',
 'ML Explanation':'Review real model output only when inference was available. No feature-attribution method is fabricated.',
 'Evidence Comparison':'Compare risk score, YARA match count and ML output for individual stored scans without treating any signal as conclusive.',
 'Investigation Report':'Open the security report or download scan history for reproducible investigation notes.',
 'Dataset Explorer':'Explore scan records actually stored by this instance. It is not a curated malware dataset.',
 'Family Research':'Review YARA rule names/tags as investigation clues; tags do not establish definitive malware-family attribution.',
 'Feature Distribution':'Summarize measured extractor features available in the stored scan records. No ground-truth accuracy is inferred.',
 'Experiment Notes':'Write reproducibility notes for a test run; these notes are held in this page session and are not uploaded.',
 'Export Research':'Export persisted scan history and a security summary for offline analysis.'};
 const Table=({items})=><div className="tablewrap"><table><thead><tr><th>File</th><th>Severity</th><th>Risk</th><th>YARA</th><th>ML</th><th>Action</th></tr></thead><tbody>{items.length?items.map(x=><tr key={x.id}><td><b>{x.filename}</b><small>{x.sha256?.slice(0,20)}…</small></td><td>{x.severity}</td><td>{x.risk_score}/100</td><td>{x.yara_count||0}</td><td>{x.ml_label||'Unavailable'}</td><td><button className="textbutton" onClick={()=>openScan(x.id)}>Inspect</button></td></tr>):<tr><td colSpan="6">No matching stored scan records yet.</td></tr>}</tbody></table></div>;
 return <div className="content"><section className="panel"><div className="panelhead"><div><h3>{page}</h3><small>{role} workflow · based on persisted scan data and authenticated API responses</small></div><Badge>{role.toUpperCase()}</Badge></div><p>{pageCopy[page]||'Workflow for the selected role.'}</p>{error&&<div className="alert error">{error}</div>}
 {page==='Administration'&&<><h4>User and role management</h4><p className="muted">Only administrators can view this table or change roles/status.</p><form className="rule-upload" onSubmit={createManagedUser}><label>Full name<input required minLength="2" value={newUserName} onChange={e=>setNewUserName(e.target.value)} placeholder="New team member"/></label><label>Email<input required type="email" value={newUserEmail} onChange={e=>setNewUserEmail(e.target.value)} placeholder="user@organization.com"/></label><label>Temporary password<input required type="password" minLength="10" value={newUserPassword} onChange={e=>setNewUserPassword(e.target.value)} placeholder="At least 10 characters"/></label><label>Role<select value={newUserRole} onChange={e=>setNewUserRole(e.target.value)}><option value="researcher">Researcher</option><option value="security_analyst">Security Analyst</option><option value="soc_member">SOC Team Member</option><option value="administrator">Administrator</option></select></label><button className="btn red" disabled={busy}>Create account</button></form><div className="tablewrap"><table><thead><tr><th>Name</th><th>Email</th><th>Role</th><th>Status</th><th>Change role</th><th>Action</th></tr></thead><tbody>{users.map(u=><tr key={u.id}><td>{u.full_name}</td><td>{u.email}</td><td>{u.role}</td><td>{u.active?'Active':'Disabled'}</td><td><select value={u.role} disabled={busy} onChange={e=>changeRole(u.id,e.target.value)}><option value="administrator">Administrator</option><option value="soc_member">SOC Team Member</option><option value="security_analyst">Security Analyst</option><option value="researcher">Researcher</option></select></td><td><button className="textbutton" disabled={busy} onClick={()=>changeStatus(u.id,!u.active)}>{u.active?'Deactivate':'Activate'}</button></td></tr>)}</tbody></table></div></>}
 {page==='Audit Review'&&<div className="tablewrap"><table><thead><tr><th>Time</th><th>Actor</th><th>Action</th><th>Target</th><th>Details</th></tr></thead><tbody>{audit.map(a=><tr key={a.id}><td>{when(a.created_at)}</td><td>{a.actor_email}</td><td>{a.action}</td><td>{a.target||'—'}</td><td><code>{JSON.stringify(a.details)}</code></td></tr>)}</tbody></table></div>}
 {page==='System Health'&&<div className="metrics"><Metric Icon={Server} label="API status" value={health?.status||'Unavailable'} sub="Public health endpoint"/><Metric Icon={Activity} label="Stored scans" value={scans.length} sub="Loaded records in workspace"/><Metric Icon={ShieldCheck} label="Model readiness" value={modelState?.available?'Ready':'Not verified'} sub="See Model Readiness for schema status"/></div>}
 {page==='Model Readiness'&&<><div className="metrics"><Metric Icon={Database} label="Artifact found" value={modelState?.model_exists?'Yes':'No'} sub={modelState?.model_path||'Configured model path'}/><Metric Icon={FileSearch} label="Schema found" value={modelState?.schema_exists?'Yes':'No'} sub={modelState?.schema_feature_count?`${modelState.schema_feature_count} declared features`:'No parsed feature count'}/><Metric Icon={ShieldAlert} label="Inference ready" value={modelState?.available?'Yes':'No'} sub="Readiness does not validate model quality"/></div><p className="muted">{modelState?.note||modelState?.schema_error||'Readiness details load from the backend.'}</p></>}
 {['Rule Updates','Rule Match Explorer','YARA Library'].includes(page)&&<>{page==='Rule Updates'&&<><form className="rule-upload" onSubmit={uploadRule}><label>Upload one reviewed rule (.yar/.yara)<input type="file" accept=".yar,.yara" onChange={e=>setRuleFile(e.target.files?.[0]||null)}/></label><button className="btn red" disabled={!ruleFile||busy}>{busy?'Validating…':'Compile and add rule'}</button><small>Single files are compiled before being added.</small></form><form className="rule-upload ruleset-upload" onSubmit={importRuleset}><label>Community/vendor ruleset ZIP<input type="file" accept=".zip,application/zip" onChange={e=>setRulesetFile(e.target.files?.[0]||null)}/></label><label>Source URL/name<input required value={rulesetSource} onChange={e=>setRulesetSource(e.target.value)} placeholder="Repository or vendor"/></label><label>Version / commit<input required value={rulesetVersion} onChange={e=>setRulesetVersion(e.target.value)} placeholder="Release or commit hash"/></label><label>License<input required value={rulesetLicense} onChange={e=>setRulesetLicense(e.target.value)} placeholder="License identifier"/></label><button className="btn red" disabled={!rulesetFile||busy}>{busy?'Validating…':'Validate and import ZIP'}</button><small>Max 20 MB compressed, 500 rule files and 50 MB expanded. Every rule must compile before any file is installed. Review upstream provenance and license; this is a manual update, not an automatic internet updater.</small></form><h4>Installed ruleset manifests</h4><div className="tablewrap"><table><thead><tr><th>Source</th><th>Version</th><th>License</th><th>Imported</th><th>Files</th></tr></thead><tbody>{rulesets.map((x,i)=><tr key={i}><td>{x.source||x.directory}</td><td>{x.version||'—'}</td><td>{x.license||'—'}</td><td>{x.imported_at||'—'}</td><td>{x.files?.length??'—'}</td></tr>)}{!rulesets.length&&<tr><td colSpan="5">No imported ruleset manifest yet.</td></tr>}</tbody></table></div></>}<div className="metrics"><Metric Icon={Database} label="Rule files" value={rules?.count??'—'} sub="Local .yar/.yara files"/><Metric Icon={ShieldCheck} label="Compiled rules" value={rules?.total_rules??'—'} sub="Successfully compiled definitions"/><Metric Icon={Activity} label="Rule inventory" value={rules?'Loaded':'Loading'} sub="No upstream auto-update is implied"/></div><div className="tablewrap"><table><thead><tr><th>Source file</th><th>Size</th><th>Rule count</th><th>Compile status</th><th>Error</th>{page==='Rule Updates'&&<th>Action</th>}</tr></thead><tbody>{(rules?.rules||[]).map(r=><tr key={r.filename}><td>{r.filename}</td><td>{r.bytes}</td><td>{r.rule_count??'—'}</td><td>{r.compile_status}</td><td>{r.error||'—'}</td>{page==='Rule Updates'&&<td><button className="textbutton" disabled={busy||r.filename==='threatlens_demo.yar'} onClick={()=>removeRule(r.filename)}>Remove</button></td>}</tr>)}</tbody></table></div><p className="muted">Only locally installed rules are counted. The demo rule is for integration testing, not a production threat-intelligence ruleset.</p></>}
 {['Alert Triage','Shift Handover'].includes(page)&&<><div className="metrics"><Metric Icon={ShieldAlert} label="High/critical records" value={high.length} sub="Stored records requiring review"/><Metric Icon={Gauge} label="Highest risk" value={high.length?Math.max(...high.map(x=>x.risk_score||0))+'/100':'—'} sub="Observed score only"/><Metric Icon={ClipboardCheck} label="Loaded scans" value={scans.length} sub="Current database history"/></div><Table items={high}/>{page==='Shift Handover'&&<a className="btn red" href={BASE+'/api/analytics/export.csv'}>Export handover scan records</a>}</>}
 {page==='Incident Queue'&&<><div className="metrics"><Metric Icon={Database} label="Open incidents" value={incidents.filter(i=>i.status==='open'||i.status==='investigating').length} sub="Persisted incident records"/><Metric Icon={ShieldAlert} label="High-risk scans" value={high.length} sub="Candidate records to escalate"/><Metric Icon={Users} label="Available assignees" value={assignees.length} sub="Active SOC/analyst/admin users"/></div><form className="rule-upload" onSubmit={createIncident}><label>Scan to escalate<select required value={incidentScanId} onChange={e=>{setIncidentScanId(e.target.value);const x=scans.find(s=>String(s.id)===e.target.value);if(x&&!incidentTitle)setIncidentTitle(`Review ${x.filename}`)}}><option value="">Choose high-risk scan</option>{high.map(x=><option value={x.id} key={x.id}>{x.filename} · {x.severity} · {x.risk_score}/100</option>)}</select></label><label>Incident title<input required minLength={3} value={incidentTitle} onChange={e=>setIncidentTitle(e.target.value)} placeholder="Incident summary"/></label><label>Initial notes<textarea rows="2" value={incidentNotes} onChange={e=>setIncidentNotes(e.target.value)} placeholder="Evidence and next action"/></label><button className="btn red" disabled={!incidentScanId||busy}>Create incident</button></form><div className="tablewrap"><table><thead><tr><th>Incident</th><th>Severity</th><th>Status</th><th>Assigned to</th><th>Change status</th><th>Assign</th><th>Evidence</th></tr></thead><tbody>{incidents.map(i=>{const sc=scans.find(x=>x.id===i.scan_id);return <tr key={i.id}><td><b>#{i.id} · {i.title}</b><small>Scan #{i.scan_id} · {i.notes||'No notes'}</small></td><td>{i.severity}</td><td>{i.status}</td><td>{assignees.find(a=>a.id===i.assigned_to)?.full_name||'Unassigned'}</td><td><select disabled={busy} value={i.status} onChange={e=>updateIncident(i.id,{status:e.target.value})}><option value="open">Open</option><option value="investigating">Investigating</option><option value="resolved">Resolved</option><option value="false_positive">False positive</option></select></td><td><select disabled={busy} value={i.assigned_to||''} onChange={e=>updateIncident(i.id,{assigned_to:e.target.value?Number(e.target.value):null})}><option value="">Unassigned</option>{assignees.map(a=><option key={a.id} value={a.id}>{a.full_name} ({a.role})</option>)}</select></td><td>{sc&&<button className="textbutton" onClick={()=>openScan(sc.id)}>Inspect scan</button>}</td></tr>})}{!incidents.length&&<tr><td colSpan="7">No incidents created yet. Escalate a high-risk scan above.</td></tr>}</tbody></table></div></>}
 {page==='Threat Timeline'&&<ECharts option={{tooltip:{trigger:'axis'},grid:{left:40,right:20,top:20,bottom:55},xAxis:{type:'category',data:[...scans].reverse().map(x=>x.created_at?new Date(x.created_at).toLocaleTimeString():String(x.id)),axisLabel:{color:'#ccc',rotate:35}},yAxis:{type:'value',min:0,max:100,axisLabel:{color:'#ccc'}},series:[{type:'line',smooth:true,data:[...scans].reverse().map(x=>x.risk_score||0),lineStyle:{color:'#ef233c'},itemStyle:{color:'#ef233c'}}]}} style={{height:320}}/>}
 {page==='Response Playbooks'&&<div className="guidegrid">{['Preserve original file hash and scan ID','Review matched YARA rule metadata and evidence','Check whether ML inference was actually available','Validate indicators in context; do not infer attribution from a single match','Record analyst disposition and escalation decision'].map((x,i)=><label className="mini-guide" key={x}><input type="checkbox"/><span>{i+1}. {x}</span></label>)}</div>}
 {['File Indicators','ML Explanation','Evidence Comparison','Investigation Report','Dataset Explorer','Family Research','Feature Distribution','Export Research'].includes(page)&&<><div className="metrics"><Metric Icon={Database} label="Records" value={scans.length} sub="Stored scan history"/><Metric Icon={ShieldAlert} label="YARA hits" value={scans.reduce((a,x)=>a+(x.yara_count||0),0)} sub="Across loaded records"/><Metric Icon={Activity} label="ML outputs" value={scans.filter(x=>x.ml_label).length} sub="Predictions recorded"/></div>{['Dataset Explorer','Family Research'].includes(page)&&<><h4>Curate scan metadata</h4><p className="muted">Annotations are human-entered research labels, not automatic ground truth. Record your evidence and source; use an independent labeled holdout before publishing performance metrics.</p><form className="rule-upload" onSubmit={saveAnnotation}><label>Scan record<select required value={annotationScanId} onChange={e=>setAnnotationScanId(e.target.value)}><option value="">Choose a stored scan</option>{scans.map(x=><option key={x.id} value={x.id}>#{x.id} · {x.filename}</option>)}</select></label><label>Research label<select value={annotationLabel} onChange={e=>setAnnotationLabel(e.target.value)}><option value="unknown">Unknown / not reviewed</option><option value="benign">Benign (reviewed)</option><option value="malware">Malware (reviewed)</option></select></label><label>Family / category<input value={annotationFamily} onChange={e=>setAnnotationFamily(e.target.value)} placeholder="Optional family hypothesis"/></label><label>Dataset source<input required value={annotationSource} onChange={e=>setAnnotationSource(e.target.value)} placeholder="Source or validation set"/></label><label>Evidence notes<textarea rows="2" value={annotationNotes} onChange={e=>setAnnotationNotes(e.target.value)} placeholder="Why this label is supported"/></label><button className="btn red" disabled={!annotationScanId||busy}>Save research annotation</button></form><div className="tablewrap"><table><thead><tr><th>Scan</th><th>Label</th><th>Family</th><th>Source</th><th>Notes</th><th>Updated</th></tr></thead><tbody>{annotations.map(a=><tr key={a.id}><td>#{a.scan_id}</td><td>{a.ground_truth}</td><td>{a.family||'—'}</td><td>{a.dataset_source}</td><td>{a.notes||'—'}</td><td>{when(a.updated_at)}</td></tr>)}{!annotations.length&&<tr><td colSpan="6">No research annotations recorded yet.</td></tr>}</tbody></table></div></>}{page==='Family Research'&&<p className="muted">Attribution is intentionally not inferred from the scan list. Open a record and examine matched rule names, tags, metadata and the context before proposing a family.</p>}{page==='Feature Distribution'&&<ECharts option={{tooltip:{trigger:'axis'},grid:{left:42,right:18,top:20,bottom:40},xAxis:{type:'category',data:['Entropy','URLs','IPs','Suspicious APIs'],axisLabel:{color:'#ccc'}},yAxis:{type:'value',axisLabel:{color:'#ccc'}},series:[{type:'bar',data:[avgFeature(scans,'entropy'),avgFeature(scans,'url_count'),avgFeature(scans,'ip_count'),avgFeature(scans,'suspicious_api_count')],itemStyle:{color:'#ef233c'}}]}} style={{height:280}}/>}<Table items={scans}/>{page==='Investigation Report'&&<a className="btn red" href={BASE+'/api/analytics/security-report'} target="_blank" rel="noreferrer">Open generated JSON report</a>}{page==='Export Research'&&<a className="btn red" href={BASE+'/api/analytics/export.csv'}>Download scan history CSV</a>}</>}
 {page==='Experiment Notes'&&<><form className="rule-upload" onSubmit={saveResearchNote}><label>Note title<input required minLength="2" value={noteTitle} onChange={e=>setNoteTitle(e.target.value)}/></label><label>Tags<input value={noteTags} onChange={e=>setNoteTags(e.target.value)} placeholder="model, yara, validation"/></label><label>Reproducibility note<textarea required rows="5" value={note} onChange={e=>setNote(e.target.value)} placeholder="Record file hash, ruleset version, expected behavior, actual result and environment…"/></label><button className="btn red" disabled={!note.trim()||busy}>Save research note</button></form><div className="guidegrid">{notes.map(x=><article className="mini-guide" key={x.id}><b>{x.title} · {when(x.created_at)}</b><small>{x.tags||'No tags'}</small><span>{x.content}</span><button className="textbutton" onClick={()=>deleteResearchNote(x.id)}>Delete note</button></article>)}</div></>}
 </section></div>;
}
function avgFeature(scans,key){const vals=scans.map(x=>Number(x.features?.[key])).filter(Number.isFinite);return vals.length?Number((vals.reduce((a,b)=>a+b,0)/vals.length).toFixed(2)):0;}

const AUTH_ROLES = [
 {value:'administrator',label:'Administrator',description:'Platform governance and user administration',responsibilities:['Approve privileged role requests','Manage users, roles and account status','Review audit events, service health and global analytics']},
 {value:'security_analyst',label:'Security Analyst',description:'Static file analysis and investigation',responsibilities:['Upload authorized samples and inspect hashes/PE metadata','Review actual YARA matches and model availability','Prepare evidence-led investigation reports']},
 {value:'soc_member',label:'SOC Team Member',description:'Threat monitoring, alerts and incidents',responsibilities:['Monitor scan history, high-risk alerts and notifications','Create and update incident records','Coordinate triage and shift handover; file upload is disabled']},
 {value:'researcher',label:'Researcher',description:'Research workspace and historical analysis',responsibilities:['Upload authorized research samples','Explore historical scan results and measured features','Record research annotations and reproducibility notes']}
];
function AuthPage({mode,setMode,onEnter,goHome}) {
 const [email,setEmail]=useState(''),[password,setPassword]=useState(''),[fullName,setFullName]=useState(''),[selectedRole,setSelectedRole]=useState('researcher'),[notice,setNotice]=useState(''),[busy,setBusy]=useState(false);
 async function submit(e) {
  e.preventDefault(); setBusy(true); setNotice('');
  try {
   if(mode==='register') {
    const result=await api('/api/auth/register',{method:'POST',body:JSON.stringify({email,password,full_name:fullName,role:selectedRole})});
    if(result.active) setNotice('Account created as Researcher. You can now sign in.');
    else setNotice('Role request submitted. An administrator must approve and activate this account before sign-in.');
    setMode('login'); setPassword('');
   } else {
    const data=await api('/api/auth/login',{method:'POST',body:JSON.stringify({email,password,role:selectedRole})});
    window.localStorage.setItem('threatlens_access_token',data.access_token);
    onEnter({email:data.user.email,role:({administrator:'Administrator',soc_member:'SOC Team Member',security_analyst:'Security Analyst',researcher:'Researcher'})[data.user.role]||'Researcher',user:data.user});
   }
  } catch(err) { setNotice(err.message); }
  finally { setBusy(false); }
 }
 const chosen=AUTH_ROLES.find(r=>r.value===selectedRole)||AUTH_ROLES[3];
 return <div className="authpage">
  <button className="backhome" onClick={goHome}>← Back to Home</button>
  <div className="authcard">
   <div className="authbrand"><span className="logo"><ShieldCheck/></span><b>THREATLENS<span> AI</span></b></div>
   <Badge kind="red">SECURE WORKSPACE</Badge>
   <h1>{mode==='login'?'Welcome back.':'Create your account.'}</h1>
   <p className="muted">{mode==='login'?'Choose the role assigned to your account, then sign in.':'Choose the workspace role you need. Privileged role requests require administrator approval.'}</p>
   <form onSubmit={submit}>
    {mode==='register'&&<label>Full name<input value={fullName} onChange={e=>setFullName(e.target.value)} required minLength={2} maxLength={120} placeholder="Your full name"/></label>}
    <label>Email<input type="email" value={email} onChange={e=>setEmail(e.target.value)} required autoComplete="email" placeholder="you@organization.com"/></label>
    <label>Password<input type="password" value={password} onChange={e=>setPassword(e.target.value)} required minLength={mode==='register'?10:1} autoComplete={mode==='register'?'new-password':'current-password'} placeholder={mode==='register'?'At least 10 characters':'Your password'}/></label>
    <label>Workspace role
     <select value={selectedRole} onChange={e=>setSelectedRole(e.target.value)} required>
      {AUTH_ROLES.map(r=><option key={r.value} value={r.value}>{r.label}</option>)}
     </select>
    </label>
    <p className="muted role-description">{chosen.description}</p><div className="role-responsibilities"><b>{chosen.label} responsibilities</b><ul>{chosen.responsibilities.map(item=><li key={item}>{item}</li>)}</ul></div>
    {mode==='register'&&selectedRole!=='researcher'&&<div className="authwarning"><LockKeyhole/><span>This role is created as pending approval. An administrator must approve and activate it. You cannot grant yourself privileged access.</span></div>}
    {notice&&<div className="alert" role="status">{notice}</div>}
    <button className="btn red full large" disabled={busy} type="submit">{busy?'Please wait…':mode==='login'?'Sign in':'Create account'} <ArrowRight size={16}/></button>
   </form>
   <p className="authswitch">{mode==='login'?"New to ThreatLens AI?":"Already have an account?"} <button type="button" onClick={()=>{setNotice('');setMode(mode==='login'?'register':'login')}}>{mode==='login'?'Register':'Log in'}</button></p>
   <div className="authwarning"><LockKeyhole/><span>Your selected login role must match the role saved to your account. API permissions are enforced by the backend.</span></div>
  </div>
 </div>;
}

export default function App(){
 const [screen,setScreen]=useState('home'),[authMode,setAuthMode]=useState('login'),[role,setRole]=useState('Security Analyst'),[email,setEmail]=useState(''),[page,setPage]=useState('Overview'),[overview,setOverview]=useState(null),[scans,setScans]=useState([]),[notices,setNotices]=useState([]),[file,setFile]=useState(null),[busy,setBusy]=useState(false),[err,setErr]=useState(''),[msg,setMsg]=useState(''),[detail,setDetail]=useState(null),[lastUpdated,setLastUpdated]=useState(null),[yaraInventory,setYaraInventory]=useState(null),[adminOverview,setAdminOverview]=useState(null);
 async function refresh(silent=false){if(!silent)setErr('');try{const [o,s,t]=await Promise.all([api('/api/analytics/overview'),api('/api/scans?limit=100'),api('/api/analytics/notifications')]);setOverview(o);setScans(s);setNotices(t.items||[]);setLastUpdated(new Date());if(!silent)setErr('');}catch(e){if(!silent)setErr(`${e.message}. API: ${BASE}. Verify backend status, VITE_API_URL and CORS.`);}}
 useEffect(()=>{if(screen!=='app')return;refresh();const id=setInterval(()=>refresh(true),15000);return()=>clearInterval(id);},[screen]);
 useEffect(()=>{if(screen==='app'&&page==='YARA Library'){api('/api/yara/rules').then(setYaraInventory).catch(e=>setErr(`YARA inventory: ${e.message}`));}},[screen,page]);
 useEffect(()=>{if(screen==='app'&&role==='Administrator'){api('/api/admin/overview').then(setAdminOverview).catch(e=>setErr(`Administrator metrics: ${e.message}`));}},[screen,role]);
 function enter({email,role}){setEmail(email);setRole(role);setPage('Overview');setScreen('app');setMsg(`Authenticated as ${email}. Role permissions are enforced by the backend.`);}
 async function scan(e){e.preventDefault();if(!file)return;setBusy(true);setErr('');setMsg('Uploading file and waiting for backend analysis…');try{const fd=new FormData();fd.append('file',file);const r=await api('/api/scans/upload',{method:'POST',body:fd});setDetail(r);setMsg(`Analysis complete · scan ${r.scan_id??r.id??''}`);setFile(null);e.target.reset();await refresh(true);}catch(x){setErr(x.message);setMsg('');}finally{setBusy(false);}}
 async function open(id){try{setDetail(await api('/api/scans/'+id));setPage('Live Scan');}catch(e){setErr(e.message);}}
 const trend=useMemo(()=>({tooltip:{trigger:'axis'},grid:{left:38,right:15,top:18,bottom:30},xAxis:{type:'category',data:(overview?.daily_trend||[]).map(x=>x.date),axisLabel:{color:'#a7a7a7'}},yAxis:{type:'value',axisLabel:{color:'#a7a7a7'},splitLine:{lineStyle:{color:'#292929'}}},series:[{type:'line',smooth:true,data:(overview?.daily_trend||[]).map(x=>x.scans),areaStyle:{opacity:.12},lineStyle:{width:3,color:'#ef233c'},itemStyle:{color:'#ef233c'}}]}),[overview]);
 const severity=useMemo(()=>({tooltip:{trigger:'item'},legend:{bottom:0,textStyle:{color:'#ccc'}},color:['#ef233c','#ff7b7b','#bdbdbd','#5f5f5f','#e4e4e4'],series:[{type:'pie',radius:['45%','70%'],data:Object.entries(overview?.severity_distribution||{}).map(([name,value])=>({name,value})),label:{color:'#eee'}}]}),[overview]);
 const verdict=useMemo(()=>({tooltip:{trigger:'axis'},grid:{left:130,right:20,top:15,bottom:20},xAxis:{type:'value',axisLabel:{color:'#aaa'},splitLine:{lineStyle:{color:'#292929'}}},yAxis:{type:'category',data:Object.keys(overview?.verdict_distribution||{}),axisLabel:{color:'#ddd'}},series:[{type:'bar',data:Object.values(overview?.verdict_distribution||{}),itemStyle:{color:'#ef233c',borderRadius:[0,5,5,0]}}]}),[overview]);
 if(screen==='home')return <PublicHome go={x=>{setAuthMode(x);setScreen('auth');}}/>;
 if(screen==='auth')return <AuthPage mode={authMode} setMode={setAuthMode} onEnter={enter} goHome={()=>setScreen('home')}/>;
 const nav=ROLES[role]?.nav||ROLES['Security Analyst'].nav; const RoleIcon=ROLE_ICONS[role]||ShieldCheck;
 return <div className="app-layout"><aside className="sidebar"><button className="brand sidebrand" onClick={()=>setScreen('home')}><span className="logo"><ShieldCheck/></span><span><b>THREATLENS<span> AI</span></b><small>SECURITY OPERATIONS</small></span></button><div className="env"><i/> LOCAL ANALYSIS ENVIRONMENT</div><div className="rolepill"><RoleIcon/><div><small>ACTIVE WORKSPACE</small><b>{role}</b></div></div><nav>{nav.map((label)=>{const I=({Overview:Activity,'Role Feature Center':ClipboardCheck,'Live Scan':ScanLine,'Scan History':Database,'Advanced Analytics':Gauge,Notifications:Bell,Administration:Users,'YARA Library':ShieldCheck,'Model Readiness':Activity,'Rule Updates':RefreshCw,'Audit Review':ClipboardCheck,'System Health':Server,'Alert Triage':ShieldAlert,'Incident Queue':Database,'Threat Timeline':Activity,'Response Playbooks':BookOpen,'Shift Handover':ClipboardCheck,'Rule Match Explorer':Search,'File Indicators':Fingerprint,'ML Explanation':Activity,'Evidence Comparison':ScanLine,'Investigation Report':FileText,'Dataset Explorer':Database,'Family Research':Microscope,'Feature Distribution':Activity,'Experiment Notes':BookOpen,'Export Research':Download})[label]||Activity;return <button key={label} className={page===label?'side-nav active':'side-nav'} onClick={()=>setPage(label)}><I size={17}/>{label}</button>})}</nav><div className="sidefoot"><small>API ENDPOINT</small><code>{BASE}</code><small>Updated {lastUpdated?lastUpdated.toLocaleTimeString():'not yet'}</small><button className="side-nav" onClick={()=>refresh()}><RefreshCw size={16}/> Refresh data</button><button className="side-nav" onClick={()=>{window.localStorage.removeItem('threatlens_access_token');setScreen('home');setDetail(null);setMsg('');setErr('');}}><LogOut size={16}/> Exit workspace</button></div></aside>
 <main className="app-main"><header className="app-header"><div><small className="eyebrow">THREAT INTELLIGENCE / {page.toUpperCase()}</small><h1>{page==='Overview'?ROLES[role].title:page}</h1><p>{page==='Overview'?ROLES[role].desc:''}</p></div><div className="header-actions"><span className="role-label"><RoleIcon size={15}/>{role}</span><button className="iconbtn" onClick={()=>refresh()} title="Refresh"><RefreshCw size={17}/></button></div></header>
 {err&&<div className="alert error"><AlertTriangle size={16}/>{err}</div>}{msg&&<div className="alert"><CheckCircle2 size={16}/>{msg}</div>}
 {page==='Overview'&&<div className="content"><section className="dashhero"><div><Badge kind="red">STATIC ANALYSIS WORKSPACE</Badge><h2>{role==='Administrator'?'Maintain platform visibility.':role==='SOC Team Member'?'Prioritize signals. Coordinate response.':role==='Researcher'?'Explore the evidence. Follow the trends.':'Inspect suspicious files.'}<br/><em>Keep evidence in context.</em></h2><p>Review actual scan records, compare signals and investigate results. Uploaded files are not executed by the analysis service.</p><button className="btn red" onClick={()=>setPage('Live Scan')}><UploadCloud size={16}/> Start a scan</button></div><div className="dash-mark"><ShieldCheck size={72}/><span>THREATLENS / LIVE WORKSPACE</span></div></section><div className="metrics"><Metric Icon={FileSearch} label="Total scans" value={n(overview?.total_scans)} sub="Stored submissions"/><Metric Icon={ShieldAlert} label="High / critical" value={n(overview?.high_risk)} sub="Elevated assessments"/><Metric Icon={Activity} label="Suspected malware" value={n(overview?.malicious_suspected)} sub="Configured evidence threshold"/><Metric Icon={Gauge} label="Average risk" value={`${overview?.average_risk_score||0}/100`} sub="Heuristic score"/></div>{role==='Administrator'&&<div className="metrics"><Metric Icon={Users} label="Registered users" value={n(adminOverview?.users)} sub="Server-side account count"/><Metric Icon={ShieldCheck} label="Active accounts" value={n(adminOverview?.active_users)} sub="Enabled accounts"/><Metric Icon={Database} label="Audit events" value={n(adminOverview?.audit_events)} sub="Persisted audit rows"/><Metric Icon={Activity} label="All scans" value={n(adminOverview?.scans)} sub="Platform-wide stored scans"/></div>}<RoleAnalytics items={scans} role={role}/><section className="panel"><div className="panelhead"><div><h3>{role==='SOC Team Member'?'Latest operational signals':role==='Researcher'?'Recent research records':role==='Administrator'?'Platform-wide recent activity':'Recent scans'}</h3><small>Live API data · {scans.length} records loaded</small></div><button className="textbutton" onClick={()=>setPage('Scan History')}>View all →</button></div><ScanTable items={overview?.recent_scans||[]} onOpen={open}/></section>{role==='Administrator'&&<section className="panel"><h3>Administration checks</h3><div className="guidegrid compact">{['Review active users and role assignments','Verify configured YARA rules','Confirm model artifact and schema readiness'].map(x=><div className="mini-guide" key={x}><CheckCircle2/><span>{x}</span></div>)}</div><p className="muted">User administration controls require corresponding authenticated backend endpoints; this bundle does not invent them.</p></section>}</div>}
 {page==='Live Scan'&&<div className="content"><div className="charts"><section className="panel"><div className="panelhead"><div><h3>Upload a file</h3><small>Static analysis only — uploaded files are never intentionally executed</small></div><UploadCloud/></div>{role!=='SOC Team Member'&&<form onSubmit={scan}><label className="drop"><input type="file" onChange={e=>setFile(e.target.files?.[0]||null)}/><UploadCloud size={34}/><b>{file?file.name:'Choose file to inspect'}</b><small>{file?`${(file.size/1024).toFixed(1)} KB`:'Choose a file within the backend upload limit'}</small></label><p className="muted">The backend hashes and inspects the file, checks installed YARA rules, parses supported file formats and attempts ML inference when compatible. A clearly labelled synthetic threat-indicator preview is also shown for UI demonstration; it never changes the actual verdict or risk score.</p><button className="btn red full" disabled={!file||busy}>{busy?'Analyzing…':'Run static analysis'}</button></form>}{role==='SOC Team Member'&&<div className="noticebox"><ShieldAlert/><p><b>Upload disabled for SOC Team Member.</b> Use scan history, alerts and incidents to monitor results. Security Analyst, Researcher and Administrator roles can submit authorized samples.</p></div>}</section><section className="panel"><h3>Analysis pipeline</h3>{[['01','File intake','Receive upload through API'],['02','Hash & indicators','Compute hashes and extract static indicators'],['03','PE inspection','Parse supported executable metadata'],['04','YARA rules','Record matched rules and metadata'],['05','ML inference','Use malware_classifier.pkl when compatible'],['06','Risk synthesis','Combine configured evidence for triage']].map(x=><div className="step" key={x[0]}><b>{x[0]}</b><div><strong>{x[1]}</strong><small>{x[2]}</small></div><span>›</span></div>)}</section></div>{detail&&<ScanDetail r={detail}/>}</div>}
 {page==='Scan History'&&<div className="content"><section className="panel"><div className="panelhead"><div><h3>Scan history</h3><small>Persisted records returned by backend</small></div><a className="btn red small" href={BASE+'/api/analytics/export.csv'}><Download size={15}/> Export CSV</a></div><ScanTable items={scans} onOpen={open}/></section></div>}
 {page==='Advanced Analytics'&&<div className="content"><div className="metrics"><Metric Icon={Database} label="Scans" value={n(overview?.total_scans)} sub="Stored records"/><Metric Icon={ShieldAlert} label="Suspicious" value={n(overview?.suspicious)} sub="Configured risk threshold"/><Metric Icon={Activity} label="High risk" value={n(overview?.high_risk)} sub="High or critical"/><Metric Icon={Gauge} label="Mean risk" value={`${overview?.average_risk_score||0}/100`} sub="Across stored scans"/></div><RoleAnalytics items={scans} role={role}/><section className="panel"><div className="panelhead"><div><h3>Security report</h3><small>Summary of stored scan evidence</small></div><a className="btn red small" href={BASE+'/api/analytics/security-report'} target="_blank" rel="noreferrer"><Download size={15}/> View JSON report</a></div><p className="muted">Charts use backend responses and update during periodic refresh. They are empty until scan records exist.</p></section></div>}
 {page==='Notifications'&&<div className="content"><section className="panel"><div className="panelhead"><div><h3>Threat notifications</h3><small>Backend-generated notification records</small></div><Badge>{notices.length} EVENTS</Badge></div>{notices.length?notices.map(x=><button className="notice" key={x.id} onClick={()=>open(x.id)}><ShieldAlert/><div><b>{x.title}</b><small>{x.verdict} · risk {x.risk_score}/100 · YARA {x.yara_count}</small><small>{when(x.created_at)}</small></div><Badge kind={String(x.severity||'').toLowerCase()}>{x.severity}</Badge></button>):<div className="empty"><Bell/><b>No notifications yet</b><small>Notifications appear when stored scans meet configured conditions.</small></div>}</section></div>}
 {page==='YARA Library'&&<div className="content"><section className="panel"><div className="panelhead"><div><h3>YARA rules library</h3><small>Local rules detected by the running backend</small></div><button className="btn ghost small" onClick={()=>refresh()}><RefreshCw size={14}/> Refresh inventory</button></div><p>YARA is a pattern-matching engine, not a bundled threat-signature database. This page lists local rule files that the backend can discover. Add licensed/trusted .yar or .yara files to <code>backend/yara_rules/</code>, then refresh and run a new scan.</p><div className="guidegrid"><div className="mini-guide"><ShieldCheck/><div><b>Official YARA engine</b><small><a href="https://github.com/VirusTotal/yara" target="_blank" rel="noreferrer">VirusTotal/YARA source repository</a></small></div></div><div className="mini-guide"><BookOpen/><div><b>Rule authoring guide</b><small><a href="https://yara.readthedocs.io/en/latest/writingrules.html" target="_blank" rel="noreferrer">Official YARA rule documentation</a></small></div></div><div className="mini-guide"><Database/><div><b>Community rules</b><small><a href="https://github.com/Yara-Rules/rules" target="_blank" rel="noreferrer">YARA-Rules community collection</a></small></div></div></div><div className="alert">Rule match rate is matched rules ÷ successfully evaluated rules. It is not a malware probability. No matches does not mean safe.</div><div id="yara-inventory"><div className="metrics"><Metric Icon={Database} label="Rule files" value={n(yaraInventory?.count)} sub="Discovered recursively"/><Metric Icon={ShieldCheck} label="Parsed rules" value={n(yaraInventory?.total_rules)} sub="Rules counted from compiled files"/><Metric Icon={Activity} label="Inventory state" value={yaraInventory?'Loaded':'Loading'} sub="Fetched from backend"/></div>{yaraInventory?.rules?.length?<div className="tablewrap"><table><thead><tr><th>Rule file</th><th>Bytes</th><th>Rules</th><th>Compile status</th><th>Error</th></tr></thead><tbody>{yaraInventory.rules.map((r,i)=><tr key={r.filename+i}><td>{r.filename}</td><td>{r.bytes}</td><td>{r.rule_count??'—'}</td><td><Badge kind={r.compile_status==='ok'?'green':r.compile_status==='error'?'red':''}>{r.compile_status}</Badge></td><td>{r.error||'—'}</td></tr>)}</tbody></table></div>:<div className="empty"><Database/><b>{yaraInventory?'No local rule files found':'Loading rule inventory…'}</b><span>Add reviewed .yar/.yara files to backend/yara_rules/. The current bundle only includes the demo rule.</span></div>}<a href={BASE+'/api/yara/rules'} target="_blank" rel="noreferrer">Open raw YARA inventory API →</a></div></section></div>}
 {page==='Role Feature Center'&&<RoleFeatureCenter role={role} scans={scans} onNavigate={setPage}/> }
 {page.startsWith('Capability:')&&<CapabilityWorkspace role={page.split(':')[1]} index={page.split(':')[2]} scans={scans} onOpenScan={open} onNavigate={setPage}/> }
 {['Model Readiness','Rule Updates','Audit Review','System Health','Alert Triage','Incident Queue','Threat Timeline','Response Playbooks','Shift Handover','Rule Match Explorer','File Indicators','ML Explanation','Evidence Comparison','Investigation Report','Dataset Explorer','Family Research','Feature Distribution','Experiment Notes','Export Research','Administration'].includes(page)&&<RoleWorkflowPage page={page} role={role} scans={scans} openScan={open} refresh={refresh}/>}
 <footer className="appfooter">ThreatLens AI · Static triage only · Analyst review required · Workspace: {role}</footer></main></div>;
}
